#include <windows.h>
#include <shlobj.h>
#include <wrl/client.h>
#include <iostream>
#include "core/unicode.hpp"
using Microsoft::WRL::ComPtr;
static void menu_items(HMENU menu,unsigned depth=0){for(int i=0;i<GetMenuItemCount(menu);++i){wchar_t name[512]{};MENUITEMINFOW info{sizeof(info)};info.fMask=MIIM_STRING|MIIM_SUBMENU|MIIM_STATE|MIIM_FTYPE;info.dwTypeData=name;info.cch=512;if(!GetMenuItemInfoW(menu,i,TRUE,&info))continue;if(info.fType&MFT_SEPARATOR)continue;std::cout<<std::string(depth*2,' ')<<crackhood::utf8(name)<<((info.fState&MFS_DISABLED)?" [disabled]":"")<<'\n';if(info.hSubMenu)menu_items(info.hSubMenu,depth+1);}}
static void inspect_menu(IShellFolder*folder,PCUITEMID_CHILD item){ComPtr<IContextMenu>context;HRESULT hr=item?folder->GetUIObjectOf(nullptr,1,&item,IID_IContextMenu,nullptr,reinterpret_cast<void**>(context.GetAddressOf())):folder->CreateViewObject(nullptr,IID_PPV_ARGS(&context));if(FAILED(hr)){std::cout<<"Menu unavailable HRESULT="<<static_cast<unsigned>(hr)<<'\n';return;}auto menu=CreatePopupMenu();hr=context->QueryContextMenu(menu,0,1,1000,CMF_NORMAL);if(SUCCEEDED(hr))menu_items(menu);DestroyMenu(menu);}
int wmain(){CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);CLSID clsid{};CLSIDFromString(L"{57B2D0D9-32DD-476a-B663-C85D2EA24AA5}",&clsid);ComPtr<IShellFolder>root;auto hr=CoCreateInstance(clsid,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&root));if(FAILED(hr)){std::cerr<<"Neighborhood unavailable "<<static_cast<unsigned>(hr)<<'\n';return 1;}PIDLIST_ABSOLUTE absolute=nullptr;hr=SHParseDisplayName(L"shell:::{57B2D0D9-32DD-476a-B663-C85D2EA24AA5}",nullptr,&absolute,0,nullptr);if(SUCCEEDED(hr)){ComPtr<IPersistFolder>persist;if(SUCCEEDED(root.As(&persist)))persist->Initialize(absolute);CoTaskMemFree(absolute);}std::cout<<"Neighborhood root background:\n";inspect_menu(root.Get(),nullptr);ComPtr<IEnumIDList>items;hr=root->EnumObjects(nullptr,SHCONTF_FOLDERS|SHCONTF_NONFOLDERS,&items);if(FAILED(hr)||!items)return 2;PITEMID_CHILD item=nullptr;while(items->Next(1,&item,nullptr)==S_OK){STRRET name{};if(SUCCEEDED(root->GetDisplayNameOf(item,SHGDN_NORMAL,&name))&&name.uType==STRRET_WSTR){std::cout<<"Root item: "<<crackhood::utf8(name.pOleStr)<<'\n';CoTaskMemFree(name.pOleStr);}inspect_menu(root.Get(),item);ComPtr<IShellFolder>console;if(SUCCEEDED(root->BindToObject(item,nullptr,IID_PPV_ARGS(&console)))){std::cout<<"Console background:\n";inspect_menu(console.Get(),nullptr);ComPtr<IEnumIDList>drives;if(SUCCEEDED(console->EnumObjects(nullptr,SHCONTF_FOLDERS|SHCONTF_NONFOLDERS,&drives))&&drives){PITEMID_CHILD drive=nullptr;if(drives->Next(1,&drive,nullptr)==S_OK){std::cout<<"First console child menu:\n";inspect_menu(console.Get(),drive);CoTaskMemFree(drive);}}}CoTaskMemFree(item);}return 0;}
